<?php $title='Logs'; ?><section class="page-head"><div><h1>Logs de atividades</h1><p>Registro de ações administrativas e eventos de segurança.</p></div></section><form class="filters" method="get"><input type="date" name="from" value="<?= e($_GET['from']??'') ?>"><input type="date" name="to" value="<?= e($_GET['to']??'') ?>"><select name="user_id"><option value="">Todos os usuários</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= ($_GET['user_id']??'')==$u['id']?'selected':'' ?>><?= e($u['name']) ?></option><?php endforeach; ?></select><select name="action"><option value="">Todas as ações</option><?php foreach($actions as $a): ?><option <?= ($_GET['action']??'')===$a?'selected':'' ?>><?= e($a) ?></option><?php endforeach; ?></select><select name="result"><option value="">Todos os resultados</option><option value="success">Sucesso</option><option value="failure">Falha</option><option value="warning">Aviso</option></select><button class="btn">Filtrar</button></form><section class="panel"><?php if(!$logs): ?><div class="empty">Nenhum registro encontrado.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Usuário</th><th>Ação</th><th>Descrição</th><th>IP</th><th>Resultado</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= e(date('d/m/Y H:i:s',strtotime($l['created_at']))) ?></td><td><?= e($l['user_name']??'Sistema') ?></td><td><code><?= e($l['action']) ?></code></td><td><?= e($l['description']) ?></td><td><?= e($l['ip_address']) ?></td><td><span class="badge <?= e($l['result']) ?>"><?= e($l['result']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>

